/*
 * CR Group Tracker – web bridge.
 *
 * index.html talks to `window.Android`. In the Android app that object is injected by MainActivity and
 * this file does nothing. In a browser (the web app on GitHub Pages) this file provides the same
 * `Android` object on top of the Apps Script backend: login, sync, members, requests, notifications,
 * settings. Everything is online-only on the web (no offline cache).
 *
 * Settings come from config.js (window.CR_CONFIG), generated by the `exportWebApp` Gradle task.
 */
(function () {
  if (window.Android) return; // Android app: the native bridge is used

  const CFG = window.CR_CONFIG || {};
  const SESSION_KEY = 'cr_web_session';
  const SYNC_INTERVAL_MS = 60000;
  const PRIVACY_URL = 'https://angappan578.github.io/cr-tracker/privacy.html';
  const LIST_HEADERS = ['memberId', 'memberName', 'contactNumber', 'joinedDate', 'managerId', 'managerName',
    'parentMemberId', 'parentMemberName', 'level', 'createdAt', 'updatedAt', 'status'];

  let session = readSession();
  let raw = new Map();          // memberId -> member as the server sent it
  let role = { isAdmin: false, isMainAdmin: false, canDecide: false, canEdit: false, requestCount: 0, unreadCount: 0, roots: [] };
  let targets = [3, 5, 6, 10, 15, 20];
  let syncing = false;
  let lastSynced = 0;
  let syncState = 'syncing';
  let syncMessage = null;
  let pageReady = false;
  let pageRequests = new Map();

  // ------------------------------------------------------------------ Backend

  async function api(action, data, auth) {
    if (!CFG.scriptUrl) throw new Error('The web app is not configured (config.js is missing).');
    const body = Object.assign({ action: action, appKey: CFG.appKey }, data || {});
    if (auth !== false && session) body.token = session.token;
    let response;
    try {
      // text/plain keeps this a "simple" request, which Apps Script answers without a CORS preflight.
      response = await fetch(CFG.scriptUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(body),
      });
    } catch (e) {
      const err = new Error('Unable to reach the server. Check your internet connection.');
      err.code = 'NETWORK';
      throw err;
    }
    let json;
    try {
      json = await response.json();
    } catch (e) {
      throw new Error('Unexpected response from the server.');
    }
    if (!json.ok) {
      const err = new Error((json.error && json.error.message) || 'Server error. Please try again.');
      err.code = json.error && json.error.code;
      if (err.code === 'AUTH_REQUIRED' || err.code === 'SESSION_EXPIRED') signOut(err.message);
      throw err;
    }
    return json.data || {};
  }

  function readSession() {
    try {
      const s = JSON.parse(localStorage.getItem(SESSION_KEY));
      return s && s.token && s.userId ? s : null;
    } catch (e) {
      return null;
    }
  }

  function saveSession(data) {
    session = { token: data.token, userId: data.user.userId, username: data.user.username };
    localStorage.setItem(SESSION_KEY, JSON.stringify(session));
  }

  function signOut(message) {
    session = null;
    localStorage.removeItem(SESSION_KEY);
    raw = new Map();
    showLogin(message);
  }

  // ------------------------------------------------------------------ Sync

  async function sync() {
    if (!session || syncing) return;
    syncing = true;
    pushStatus('syncing');
    try {
      const data = await api('GET_MEMBERS');
      raw = new Map((data.members || []).filter(m => m.status !== 'INACTIVE').map(m => [m.memberId, m]));
      if (Array.isArray(data.levelTargets) && data.levelTargets.length === 6) targets = data.levelTargets;
      const me = data.me || {};
      role = {
        isAdmin: !!me.isAdmin,
        isMainAdmin: !!me.isMainAdmin,
        canDecide: !!me.canDecide,
        canEdit: !!me.canEdit || !!me.isAdmin,
        requestCount: data.requestCount || 0,
        unreadCount: data.unreadCount || 0,
        roots: data.rootNames || [],
      };
      lastSynced = Date.now();
      syncMessage = null;
      pushMembers();
      pushStatus('synced');
    } catch (e) {
      syncMessage = e.message;
      pushStatus(e.code === 'NETWORK' ? 'offline' : 'failed');
    } finally {
      syncing = false;
    }
  }

  function webMembers() {
    return [...raw.values()]
      .sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0))
      .map(m => ({
        id: m.memberId,
        name: m.memberName || '',
        doj: m.joinedDate || '',
        referrer: m.managerId || null,
        contact: m.contactNumber || '',
        level: m.level === null || m.level === undefined ? -1 : m.level,
        addedBy: m.addedByUsername || '',
        canEdit: role.canEdit,
        withdrawn: role.isAdmin && !!m.depositWithdrawn,
      }));
  }

  function pushMembers() {
    if (!pageReady || !session) return;
    window.onMembersUpdated(webMembers(), targets, {
      username: session.username,
      isAdmin: role.isAdmin,
      isMainAdmin: role.isMainAdmin,
      requestCount: role.requestCount,
      unreadCount: role.unreadCount,
      canDecide: role.canDecide,
      roots: role.roots,
      canEdit: role.canEdit,
    });
  }

  function pushStatus(state) {
    syncState = state;
    if (!pageReady) return;
    window.onSyncStatus({
      state: state, pending: 0, lastSynced: lastSynced,
      message: state === 'failed' ? syncMessage : null,
      username: session ? session.username : '',
    });
  }

  /** Sends member changes to the server; shows a message for anything refused, then refreshes. */
  async function pushChanges(list) {
    try {
      const data = await api('SYNC_MEMBERS', { members: list });
      const refused = (data.results || []).filter(r => r.result === 'rejected' || r.result === 'forbidden');
      if (refused.length) alert(refused.length + ' change(s) could not be saved: ' + (refused[0].message || 'not allowed'));
    } catch (e) {
      alert(e.message);
    }
    await sync();
  }

  function toRemote(m, changes) {
    return Object.assign({
      memberId: m.memberId,
      memberName: m.memberName,
      contactNumber: m.contactNumber || '',
      joinedDate: m.joinedDate || '',
      managerId: m.managerId || '',
      parentMemberId: m.managerId || '',
      level: m.level,
      createdAt: m.createdAt,
      updatedAt: Date.now(),
      status: 'ACTIVE',
      depositWithdrawn: !!m.depositWithdrawn,
    }, changes || {});
  }

  /** "+91 9876543210" from the form's country code and number; '' if no number. */
  function contactFrom(input) {
    const digits = String(input.contact || '').replace(/\D/g, '');
    if (!digits) return '';
    const code = String(input.countryCode || '91').replace(/\D/g, '');
    if (code === '91' && !/^[6-9]\d{9}$/.test(digits)) throw new Error('Enter a valid 10-digit Indian mobile number.');
    if (digits.length < 6 || digits.length > 14) throw new Error('Enter a valid contact number.');
    return '+' + code + ' ' + digits;
  }

  function result(obj) {
    return JSON.stringify(obj);
  }

  // ------------------------------------------------------------------ Small modal used for lists and forms

  function injectStyles() {
    const css = `
      .crw-modal { position: fixed; inset: 0; z-index: 300; display: flex; align-items: flex-start; justify-content: center;
        padding: 24px 12px; overflow-y: auto; background: rgba(3, 7, 12, 0.6); }
      .crw-card { width: 100%; max-width: 480px; padding: 18px; border-radius: 18px; background: var(--panel, #111922);
        color: var(--text, #e6edf3); border: 1px solid var(--cyan, #22d3ee); box-shadow: 0 20px 50px rgba(0,0,0,0.45); }
      .crw-card h3 { margin: 0 0 12px; font-size: 18px; }
      .crw-item { padding: 12px; border-radius: 12px; margin-bottom: 8px; background: var(--panel-2, #16212c);
        border: 1px solid var(--line, #223140); cursor: default; }
      .crw-item.click { cursor: pointer; }
      .crw-item .t { font-weight: 700; }
      .crw-item .s { font-size: 12.5px; color: var(--muted, #8b98a5); margin-top: 3px; line-height: 1.5; }
      .crw-actions { display: flex; gap: 8px; margin-top: 12px; flex-wrap: wrap; }
      .crw-actions button { flex: 1; padding: 12px; border-radius: 12px; font-weight: 700; font-size: 14px; cursor: pointer;
        border: 1px solid var(--line, #223140); background: var(--panel-2, #16212c); color: var(--text, #e6edf3); }
      .crw-actions button.primary { background: var(--cyan-strong, #00e5ff); color: var(--on-cyan, #00262c); border-color: transparent; }
      .crw-actions button.danger { color: var(--danger, #f87171); }
      .crw-row { display: flex; align-items: center; gap: 10px; padding: 10px 4px; border-bottom: 1px solid var(--line, #223140); }
      .crw-row input[type=checkbox] { width: 22px; height: 22px; }
      .crw-row select, .crw-row input[type=number] { width: auto; flex: 1; padding: 8px; }
      .crw-status { display: inline-block; font-size: 11px; font-weight: 800; padding: 3px 8px; border-radius: 8px; margin-top: 6px; }
      .crw-status.pending { color: #fff; background: #ef4444; }
      .crw-status.accepted { color: #fff; background: #22c55e; }
      .crw-status.rejected { color: #fff; background: #8b98a5; }
      .crw-unread { border-color: var(--cyan, #22d3ee); }
      /* Login */
      .crw-login { position: fixed; inset: 0; z-index: 250; overflow-y: auto; background: #0b1016; color: #e6edf3;
        display: flex; justify-content: center; align-items: flex-start; padding: 40px 16px; font-family: 'Segoe UI', Roboto, Arial, sans-serif; }
      .crw-login .box { width: 100%; max-width: 400px; padding: 24px; border-radius: 20px; background: #111922; border: 1px solid #223140; text-align: center; }
      .crw-login img { width: 200px; max-width: 80%; border-radius: 16px; }
      .crw-login .wel { margin-top: 14px; font-size: 12px; letter-spacing: 3px; color: #8b98a5; text-transform: uppercase; }
      .crw-login h1 { margin: 2px 0 6px; font-family: Georgia, 'Times New Roman', serif; font-size: 26px;
        background: linear-gradient(135deg, #a67c00, #f5d76e 40%, #d4af37 60%, #f8e7a4); -webkit-background-clip: text;
        background-clip: text; -webkit-text-fill-color: transparent; }
      .crw-login .sub { color: #8b98a5; font-size: 14px; margin-bottom: 16px; }
      .crw-login input { width: 100%; margin-bottom: 10px; padding: 13px; border-radius: 12px; border: 1px solid #223140;
        background: #0d151d; color: #e6edf3; font-size: 15px; box-sizing: border-box; }
      .crw-login .go { width: 100%; padding: 14px; border: none; border-radius: 12px; background: #22d3ee; color: #00262c;
        font-weight: 800; font-size: 16px; cursor: pointer; }
      .crw-login .link { background: none; border: none; color: #22d3ee; font-weight: 700; padding: 10px; cursor: pointer; font-size: 14px; }
      .crw-login .err { color: #f87171; font-size: 13px; min-height: 18px; margin: 4px 0 8px; }
      .crw-login .or { color: #8b98a5; font-size: 13px; margin: 14px 0 10px; }
      .crw-login #crwGoogle { display: flex; justify-content: center; }`;
    const style = document.createElement('style');
    style.textContent = css;
    document.head.appendChild(style);
  }

  /** buttons: [{ label, cls, onClick }] – onClick returning false keeps the modal open. */
  function modal(title, html, buttons) {
    const wrap = document.createElement('div');
    wrap.className = 'crw-modal';
    wrap.innerHTML = `<div class="crw-card"><h3></h3><div class="crw-body">${html}</div><div class="crw-actions"></div></div>`;
    wrap.querySelector('h3').textContent = title;
    const actions = wrap.querySelector('.crw-actions');
    const close = () => wrap.remove();
    (buttons || [{ label: 'Close' }]).forEach(b => {
      const btn = document.createElement('button');
      btn.textContent = b.label;
      if (b.cls) btn.className = b.cls;
      btn.onclick = async () => {
        if (b.onClick) {
          const keep = await b.onClick(wrap);
          if (keep === false) return;
        }
        close();
      };
      actions.appendChild(btn);
    });
    wrap.addEventListener('click', e => { if (e.target === wrap) close(); });
    document.body.appendChild(wrap);
    return wrap;
  }

  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const when = ms => ms ? new Date(ms).toLocaleString([], { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }) : '';

  // ------------------------------------------------------------------ Login

  let loginMode = 'login';

  function showLogin(message) {
    let el = document.getElementById('crwLogin');
    if (!el) {
      el = document.createElement('div');
      el.id = 'crwLogin';
      el.className = 'crw-login';
      el.innerHTML = `<div class="box">
          <img src="cr_logo.jpg" alt="CR Group Tracker logo">
          <div class="wel">Welcome to</div>
          <h1>CR Group Tracker</h1>
          <div class="sub" id="crwSub">Log in to see your members</div>
          <input id="crwUser" placeholder="Username" autocomplete="username" autocapitalize="none">
          <input id="crwEmail" placeholder="E-mail (optional, for password reset)" type="email" style="display:none">
          <input id="crwPass" placeholder="Password" type="password" autocomplete="current-password">
          <input id="crwConfirm" placeholder="Confirm password" type="password" style="display:none">
          <div class="err" id="crwErr"></div>
          <button class="go" id="crwGo">Login</button>
          <div><button class="link" id="crwForgot">Forgot password?</button></div>
          <div id="crwGoogleBox"><div class="or">— or —</div><div id="crwGoogle"></div></div>
          <div><button class="link" id="crwMode">New user? Create an account</button></div>
          <div class="or">An app for CR Group members to track their member tree.<br>
            <a href="${PRIVACY_URL}" target="_blank" rel="noopener" style="color:#22d3ee">Privacy Policy</a></div>
        </div>`;
      document.body.appendChild(el);
      el.querySelector('#crwGo').onclick = submitLogin;
      el.querySelector('#crwPass').onkeydown = e => { if (e.key === 'Enter' && loginMode === 'login') submitLogin(); };
      el.querySelector('#crwMode').onclick = () => { loginMode = loginMode === 'login' ? 'register' : 'login'; updateLoginMode(); };
      el.querySelector('#crwForgot').onclick = forgotPassword;
      setupGoogle();
    }
    el.style.display = 'flex';
    loginMode = 'login';
    updateLoginMode();
    el.querySelector('#crwErr').textContent = message || '';
  }

  function updateLoginMode() {
    const reg = loginMode === 'register';
    const $ = id => document.getElementById(id);
    $('crwEmail').style.display = reg ? '' : 'none';
    $('crwConfirm').style.display = reg ? '' : 'none';
    $('crwForgot').style.display = reg ? 'none' : '';
    $('crwGo').textContent = reg ? 'Create account' : 'Login';
    $('crwSub').textContent = reg ? 'Create your account' : 'Log in to see your members';
    $('crwMode').textContent = reg ? 'Already have an account? Log in' : 'New user? Create an account';
    $('crwErr').textContent = '';
  }

  async function submitLogin() {
    const $ = id => document.getElementById(id);
    const username = $('crwUser').value.trim().toLowerCase();
    const password = $('crwPass').value;
    const err = $('crwErr');
    err.textContent = '';
    if (!/^[a-z0-9_.]{3,30}$/.test(username)) return (err.textContent = 'Username: 3-30 letters, numbers, dot or underscore.');
    if (!password) return (err.textContent = 'Enter your password.');
    if (loginMode === 'register') {
      if (password.length < 6) return (err.textContent = 'Password must be at least 6 characters.');
      if (password !== $('crwConfirm').value) return (err.textContent = 'Passwords do not match.');
    }
    $('crwGo').disabled = true;
    try {
      const data = loginMode === 'register'
        ? await api('REGISTER', { username: username, password: password, email: $('crwEmail').value.trim() || undefined }, false)
        : await api('LOGIN', { username: username, password: password }, false);
      afterLogin(data);
    } catch (e) {
      err.textContent = e.message;
    } finally {
      $('crwGo').disabled = false;
    }
  }

  function afterLogin(data) {
    saveSession(data);
    document.getElementById('crwLogin').style.display = 'none';
    pushStatus('syncing');
    sync();
  }

  function forgotPassword() {
    const identifier = prompt('Enter your username or e-mail:', document.getElementById('crwUser').value.trim());
    if (!identifier) return;
    api('FORGOT_PASSWORD', { identifier: identifier.trim().toLowerCase() }, false).then(data => {
      const code = prompt((data.message || 'A code was sent to your e-mail.') + '\n\nEnter the 6-digit code:');
      if (!code) return;
      const pass = prompt('New password (at least 6 characters):');
      if (!pass) return;
      return api('RESET_PASSWORD', { identifier: identifier.trim().toLowerCase(), code: code.trim(), newPassword: pass }, false)
        .then(afterLogin);
    }).catch(e => alert(e.message));
  }

  // Sign in with Google (Google Identity Services); needs this site in the OAuth client's JavaScript origins.
  function setupGoogle() {
    const box = document.getElementById('crwGoogleBox');
    if (!CFG.googleClientId) { box.style.display = 'none'; return; }
    const script = document.createElement('script');
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.onload = () => {
      google.accounts.id.initialize({
        client_id: CFG.googleClientId,
        callback: response => {
          api('GOOGLE_SIGN_IN', { idToken: response.credential }, false)
            .then(afterLogin)
            .catch(e => { document.getElementById('crwErr').textContent = e.message; });
        },
      });
      google.accounts.id.renderButton(document.getElementById('crwGoogle'),
        { theme: 'filled_black', size: 'large', shape: 'pill', text: 'signin_with', width: 300 });
    };
    script.onerror = () => { box.style.display = 'none'; };
    document.head.appendChild(script);
  }

  // ------------------------------------------------------------------ Requests

  async function pushRequests(mine) {
    try {
      const data = await api('GET_REQUESTS', { mine: mine });
      const list = (data.requests || []).map(r => ({
        id: r.requestId, type: r.type || 'MEMBER', memberName: r.memberName || '', requestedBy: r.requestedBy || '',
        contact: r.contactNumber || '', joinedDate: r.joinedDate || '',
        managerName: r.managerId && raw.has(r.managerId) ? raw.get(r.managerId).memberName : null,
        level: r.level, rootName: r.rootName || '', status: r.status || 'PENDING', handledBy: r.handledBy || '',
        note: r.note || '', createdAt: r.createdAt || 0,
      }));
      if (!mine) pageRequests = new Map(list.map(r => [r.id, r]));
      window.onRequestsLoaded(list, mine, null);
      return list;
    } catch (e) {
      window.onRequestsLoaded(null, mine, e.message);
      return [];
    }
  }

  async function decide(id, approve) {
    try {
      const data = await api('HANDLE_REQUEST', { requestId: id, approve: approve });
      if (data.member) window.celebrate(data.member.memberName);
      else alert(approve ? 'Request accepted.' : 'Request rejected.');
    } catch (e) {
      alert(e.message);
    }
    await sync();
    pushRequests(false);
  }

  function requestDetails(r) {
    const access = r.type === 'ADMIN' || r.type === 'EDIT';
    const html = access
      ? `<div class="crw-item"><div class="t">${esc(r.requestedBy)}</div><div class="s">asked for ${r.type === 'EDIT' ? 'edit access (add and edit members)' : 'admin access'}.<br>${esc(when(r.createdAt))}</div></div>`
      : `<div class="crw-item"><div class="t">${esc(r.memberName)}</div><div class="s">
          Contact: ${esc(r.contact || '—')}<br>Joined: ${esc(r.joinedDate || '—')}<br>
          Manager: ${esc(r.managerName || '— (root member)')}<br>
          Level: ${r.level === null || r.level === undefined ? '—' : r.level === 0 ? 'Root' : 'Level ' + r.level}<br>
          ${r.rootName ? 'To: ' + esc(r.rootName) + '<br>' : ''}Requested by ${esc(r.requestedBy)} · ${esc(when(r.createdAt))}</div></div>`;
    modal(access ? 'Access request' : 'Request from ' + r.requestedBy, html, [
      { label: '✅ Accept Request', cls: 'primary', onClick: () => decide(r.id, true) },
      { label: '❌ Reject', cls: 'danger', onClick: () => { if (confirm('Reject this request?')) decide(r.id, false); else return false; } },
      { label: 'Cancel' },
    ]);
  }

  async function showMyRequests() {
    let list;
    try {
      list = (await api('GET_REQUESTS', { mine: true })).requests || [];
    } catch (e) {
      return alert(e.message);
    }
    const html = list.length ? list.map(r => {
      const status = r.status === 'APPROVED' ? '<span class="crw-status accepted">✅ Accepted by ' + esc(r.handledBy) + '</span>'
        : r.status === 'REJECTED' ? '<span class="crw-status rejected">❌ Rejected by ' + esc(r.handledBy) + '</span>'
        : '<span class="crw-status pending">⏳ Pending</span>';
      const title = r.type === 'ADMIN' ? '🔑 Admin access' : r.type === 'EDIT' ? '✏️ Edit access'
        : esc(r.memberName) + (r.rootName ? ' → ' + esc(r.rootName) : '');
      return `<div class="crw-item"><div class="t">${title}</div>${status}
          ${r.note ? '<div class="s">Note: ' + esc(r.note) + '</div>' : ''}<div class="s">${esc(when(r.createdAt))}</div></div>`;
    }).join('') : '<div class="crw-item"><div class="s">You have not sent any requests yet.</div></div>';
    modal('📋 My Requests', html);
  }

  async function requestAccess(edit) {
    const what = edit ? 'edit access (add and edit members)' : 'admin access';
    if (!confirm('Ask the main admins for ' + what + '?')) return;
    try {
      alert((await api('REQUEST_ADMIN', { access: edit ? 'EDIT' : 'ADMIN' })).message);
    } catch (e) {
      alert(e.message);
    }
  }

  // ------------------------------------------------------------------ Notifications

  async function showNotifications() {
    let list;
    try {
      list = (await api('GET_NOTIFICATIONS')).notifications || [];
      if (list.some(n => !n.read)) {
        api('MARK_NOTIFICATIONS_READ').catch(() => {});
        role.unreadCount = 0;
        pushMembers();
      }
    } catch (e) {
      return alert(e.message);
    }
    const html = list.length ? list.map((n, i) => `<div class="crw-item click ${n.read ? '' : 'crw-unread'}" data-i="${i}">
        <div class="t">${n.read ? '' : '🔴 '}${esc(n.title)}</div><div class="s">${esc(n.message)}<br>${esc(when(n.createdAt))}</div></div>`).join('')
      : '<div class="crw-item"><div class="s">No notifications yet.</div></div>';
    const buttons = [{ label: 'Close' }];
    if (role.canDecide) buttons.unshift({ label: '📝 Accept Requests', cls: 'primary', onClick: () => window.showTab('requests') });
    const wrap = modal('🔔 Notifications', html, buttons);
    wrap.querySelectorAll('[data-i]').forEach(el => {
      el.onclick = async () => {
        const n = list[Number(el.dataset.i)];
        wrap.remove();
        if ((n.type === 'MEMBER_REQUEST' || n.type === 'ADMIN_REQUEST') && role.canDecide) {
          const pending = await pushRequests(false);
          const r = pending.find(x => x.id === n.requestId);
          if (r) requestDetails(r); else alert('This request was already accepted or rejected.');
        } else if (n.requestId) {
          showMyRequests();
        }
      };
    });
  }

  // ------------------------------------------------------------------ Settings (main admins), targets

  async function showSettings() {
    let users, roots;
    try {
      [users, roots] = await Promise.all([api('GET_USERS').then(d => d.users || []), api('GET_ROOTS').then(d => d.roots || [])]);
    } catch (e) {
      return alert(e.message);
    }
    const userOptions = sel => '<option value="">— Not linked —</option>' + users.map(u =>
      `<option value="${esc(u.userId)}" ${u.userId === sel ? 'selected' : ''}>${esc(u.username)}${u.email ? ' (' + esc(u.email) + ')' : ''}</option>`).join('');
    const html = `<div class="crw-item"><div class="t">👑 Admin users</div>${users.map(u => `
        <label class="crw-row"><input type="checkbox" data-user="${esc(u.userId)}" ${u.isAdmin ? 'checked' : ''} ${u.isMainAdmin ? 'disabled' : ''}>
        <span>${esc(u.username)}${u.email ? ' <small>(' + esc(u.email) + ')</small>' : ''}${u.isMainAdmin ? ' ★ main admin' : ''}</span></label>`).join('')}</div>
      <div class="crw-item"><div class="t">🌳 Root users (accept member requests)</div><div id="crwRoots">${roots.map(r => `
        <div class="crw-row"><input type="text" value="${esc(r.name)}" data-root-name style="flex:1">
        <select data-root-user>${userOptions(r.userId)}</select>
        <button onclick="this.parentNode.remove()" title="Remove">✕</button></div>`).join('')}</div>
        <button id="crwAddRoot" style="margin-top:8px;padding:8px 12px;border-radius:10px">＋ Add root</button></div>`;
    const wrap = modal('⚙️ Settings', html, [
      { label: '💾 Save', cls: 'primary', onClick: async w => {
        try {
          const changes = [...w.querySelectorAll('[data-user]')].filter(box => !box.disabled &&
            box.checked !== !!(users.find(u => u.userId === box.dataset.user) || {}).isAdmin);
          for (const box of changes) await api('SET_ADMIN', { userId: box.dataset.user, admin: box.checked });
          const newRoots = [...w.querySelectorAll('#crwRoots .crw-row')].map(row => ({
            name: row.querySelector('[data-root-name]').value.trim(),
            userId: row.querySelector('[data-root-user]').value,
          })).filter(r => r.name);
          await api('SET_ROOTS', { roots: newRoots });
          alert('Settings saved');
          sync();
        } catch (e) {
          alert(e.message);
          return false;
        }
      } },
      { label: 'Cancel' },
    ]);
    wrap.querySelector('#crwAddRoot').onclick = () => {
      const row = document.createElement('div');
      row.className = 'crw-row';
      row.innerHTML = `<input type="text" placeholder="Root name" data-root-name style="flex:1"><select data-root-user>${userOptions('')}</select>
        <button onclick="this.parentNode.remove()" title="Remove">✕</button>`;
      wrap.querySelector('#crwRoots').appendChild(row);
    };
  }

  function editLevelTargets() {
    const html = targets.map((t, i) => `<label class="crw-row"><span style="flex:1">Level ${i + 1} manager</span>
        <input type="number" min="0" max="1000" value="${t}" data-target></label>`).join('');
    modal('🎯 Level Targets', html, [
      { label: '💾 Save', cls: 'primary', onClick: async w => {
        const values = [...w.querySelectorAll('[data-target]')].map(i => Number(i.value));
        if (values.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) { alert('Enter a number from 0 to 1000 for every level.'); return false; }
        try {
          await api('SET_LEVEL_TARGETS', { targets: values });
          await sync();
        } catch (e) {
          alert(e.message);
          return false;
        }
      } },
      { label: 'Cancel' },
    ]);
  }

  // ------------------------------------------------------------------ Export (CSV)

  function exportCsv() {
    const names = new Map([...raw.values()].map(m => [m.memberId, m.memberName]));
    const rows = [LIST_HEADERS].concat([...raw.values()].map(m => {
      const manager = names.get(m.managerId) || '';
      return [m.memberId, m.memberName, m.contactNumber || '', m.joinedDate || '', m.managerId || '', manager,
        m.managerId || '', manager, m.level, new Date(m.createdAt || 0).toISOString(), new Date(m.updatedAt || 0).toISOString(), 'ACTIVE'];
    }));
    const csv = rows.map(r => r.map(v => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"').join(',')).join('\r\n');
    const link = document.createElement('a');
    link.href = URL.createObjectURL(new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8' }));
    link.download = 'cr_group_network.csv';
    link.click();
    setTimeout(() => URL.revokeObjectURL(link.href), 5000);
  }

  // ------------------------------------------------------------------ The `Android` object index.html uses

  window.Android = {
    onPageReady() {
      pageReady = true;
      if (!session) { showLogin(); return; }
      pushStatus('syncing');
      if (raw.size) pushMembers();
      sync();
    },

    syncNow() { sync(); },

    saveMember(json) {
      const input = JSON.parse(json);
      const name = String(input.name || '').trim();
      if (!name) return result({ ok: false, error: 'Please enter the member name.' });
      if (!role.canEdit) return result({ ok: false, error: 'Only admins and editors can add or edit members.' });
      let contact;
      try { contact = contactFrom(input); } catch (e) { return result({ ok: false, error: e.message }); }
      if (input.managerId && !raw.has(input.managerId)) return result({ ok: false, error: 'The selected manager no longer exists.' });
      if (contact && !input.allowDuplicate) {
        const twin = [...raw.values()].find(m => m.contactNumber === contact && m.memberId !== input.id);
        if (twin) return result({ ok: false, code: 'DUPLICATE', error: twin.memberName + ' already has the contact number ' + contact + '.' });
      }
      const now = Date.now();
      const existing = raw.get(input.id);
      if (!input.isNew && !existing) return result({ ok: false, error: 'This member no longer exists.' });
      const member = toRemote(existing || { memberId: input.id, createdAt: now }, {
        memberName: name, contactNumber: contact, joinedDate: input.doj || '',
        managerId: input.managerId || '', parentMemberId: input.managerId || '',
        level: Number.isInteger(input.level) ? input.level : null, updatedAt: now,
      });
      if (input.isNew) delete member.depositWithdrawn;
      raw.set(member.memberId, Object.assign({}, existing || {}, member)); // show it straight away
      pushMembers();
      pushChanges([member]);
      return result({ ok: true, memberId: member.memberId });
    },

    requestMember(json) {
      const input = JSON.parse(json);
      let contact;
      try { contact = contactFrom(input); } catch (e) { return result({ ok: false, error: e.message }); }
      if (!input.rootName) return result({ ok: false, error: 'Choose which root to send the request to.' });
      api('REQUEST_MEMBER', {
        rootName: input.rootName,
        member: { memberName: String(input.name || '').trim(), contactNumber: contact, joinedDate: input.doj || '',
                  managerId: input.managerId || '', level: Number.isInteger(input.level) ? input.level : null, status: 'ACTIVE' },
      }).catch(e => alert('The request could not be sent: ' + e.message));
      return result({ ok: true, message: 'Your request to add ' + String(input.name || '').trim() + ' is being sent to ' + input.rootName + '.' });
    },

    deleteMember(id) {
      const m = raw.get(id);
      if (!m) return;
      const children = [...raw.values()].filter(c => c.managerId === id);
      const manager = m.managerId && raw.get(m.managerId);
      let text = 'Delete ' + m.memberName + '?';
      if (children.length) {
        text += '\n\n' + children.length + ' member(s) under ' + m.memberName + ' will be moved to ' +
          (manager ? manager.memberName : 'the root (no manager)') + '. They are NOT deleted.';
      }
      if (!confirm(text)) return;
      const changes = children.map(c => toRemote(c, { managerId: m.managerId || '', parentMemberId: m.managerId || '' }));
      changes.push(toRemote(m, { status: 'INACTIVE' }));
      raw.delete(id);
      pushMembers();
      pushChanges(changes);
    },

    setDepositWithdrawn(id, withdrawn) {
      const m = raw.get(id);
      if (!m) return result({ ok: false, error: 'This member no longer exists.' });
      if (!role.isAdmin) return result({ ok: false, error: 'Only admins can mark deposits.' });
      m.depositWithdrawn = withdrawn;
      pushMembers();
      pushChanges([toRemote(m, { depositWithdrawn: withdrawn })]);
      return result({ ok: true });
    },

    importMembers() { return result({ ok: false, error: 'Not available on the web.' }); },
    loadRequests(mine) { pushRequests(mine); },
    decideRequest(id, approve) { decide(id, approve); },
    openRequest(id) { const r = pageRequests.get(id); if (r) requestDetails(r); },
    showRequests() { window.showTab('requests'); },
    showMyRequests() { showMyRequests(); },
    requestAdminAccess() { requestAccess(false); },
    requestEditAccess() { requestAccess(true); },
    showNotifications() { showNotifications(); },
    showSettings() { showSettings(); },
    editLevelTargets() { editLevelTargets(); },
    exportSpreadsheet() { exportCsv(); },
    importSpreadsheet() { alert('Uploading Excel files is available in the Android app.'); },
    showClearOptions() { if (confirm('Reload all members from Google Sheets?')) sync(); },
    openPrivacyPolicy() { window.open(PRIVACY_URL, '_blank', 'noopener'); },

    logout() {
      if (!confirm('Log out of ' + (session ? session.username : '') + '?')) return;
      const token = session && session.token;
      if (token) api('LOGOUT', { token: token }, false).catch(() => {});
      signOut();
    },
  };

  injectStyles();
  setInterval(() => { if (document.visibilityState === 'visible') sync(); }, SYNC_INTERVAL_MS);
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') sync(); });
})();
